strictInputTypeBindings.sourceExcerpt:
export type PropertyInput = {
  name: string;
  city: string;
  district: string;
  street: string;
  currency: "TWD" | "USD";
  ownerMode: "new" | string;
  ownerName: string;
  ownerPhone: string;
  ownerEmail: string;
  canViewTenantPhone: boolean;
  unitLabel: string;
  floor: string;
  doorSupplement?: string;
  rentalMode: "whole_unit" | "by_room";
  rooms: { label: string; roomType: string; baseRentMajor: number }[];
  extraUnits?: { label: string; floor: string; door: string; rooms: { label: string; roomType: string; baseRentMajor: number }[] }[];
  electric?: {
    split: "even" | "sub" | "owner" | "reading" | "days";
    rateMajor: number | null;
    openings: (number | null)[];
  } | null;
  submitToken?: string;
};

export type LeaseInput = {
  roomId: string;
  tenantName: string;
  tenantPhone: string;
  tenantEmail: string;
  /** Empty or "new" creates a contact. A contact id reuses that 租客 in this firm. */
  tenantContactId?: string;
  lineUserId: string;
  startDate: string;
  endDate: string;
  rentMajor: number | string | null;
  depositMonths: number | string | null;
  depositReason: string;
  dueDay: number | null;
  splitMethod: "even" | "days_occupied" | "sub_meter";
  periodStart: string;
  periodEnd: string;
  billTotalMajor: number | null;
  usageKwh: number | null;
  rateMajor: number | null;
  rateSource: "fixed_rate" | "bill_average";
  overrideReason: string;
  subUsages: { roomId: string; kwh: number }[];
  /** Client UUID for this create attempt. A retry with the same key returns the first lease. */
  idempotencyKey?: string | null;
  /** Absent for legacy clients; an explicit choice opts into the captured basis. */
  firstPeriodProrate?: boolean;
};

export type SpaceInput = {
  propertyId: string;
  ownerContactId: string;
  kind: string;
  floor: string;
  roomLabel: string;
  roomType: string;
  area: number | null;
  rentMajor: number;
  electricityMethod: string;
  ratePerKwh: number | null;
  rateCapReason: string;
  taipowerKwh: number | null;
  taipowerAmountMajor: number | null;
  notes: string;
};

export type PropertyElectricityInput = {
  serial: string;
  split: string;
  bill: string;
  usage: string;
  rate: string;
};

export type RepairInput = {
  status: string;
  note: string;
  internal: boolean;
  vendorName: string;
  estimated: string;
  finalCost: string;
  costBearer: string;
  scheduledOn: string;
  completedOn: string;
  postExpense: boolean;
};

export type ExpenseDraft = {
  propertyId: string;
  unitId?: string;
  category: string;
  /** Already integer cents, for callers that did not start from form text. */
  amountCents?: number;
  /** Form text. Parsed to cents inside normalizeExpense. */
  amountText?: string;
  incurredOn?: string;
  vendorName?: string;
  description?: string;
  receiptName?: string;
};
